// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { BASICS, CAPTIONS, CHECKS, COUNTS, OPEN_GRAPH, TWITTER } from './script'

const COPIED = 'og-2'

const build: Build = ({
  tl,
  q,
  qa,
  step,
  final,
  move,
  click,
  count,
  scramble,
  wait,
  cursorOut,
}) => {
  step(0)
  BASICS.forEach((row, index) => {
    tl.fromTo(
      q(`basic-${index}`),
      { opacity: 0, y: 6 },
      { opacity: 1, y: 0, duration: 0.25 },
      index === 0 ? 0.3 : '<0.15',
    )
    scramble(`basic-${index}-value`, row.value, { at: '<', duration: 0.7, chars: 'lowerCase' })
  })

  step(1, '+=0.3')
  tl.fromTo(
    qa('check'),
    { opacity: 0, scale: 0.85 },
    { opacity: 1, scale: 1, duration: 0.3, stagger: 0.08, ease: 'back.out(2.5)' },
  )
  tl.fromTo(
    qa('count'),
    { opacity: 0, scale: 0.85 },
    { opacity: 1, scale: 1, duration: 0.3, stagger: 0.08, ease: 'back.out(2.5)' },
    '<0.2',
  )
  COUNTS.forEach((item, index) =>
    count(`count-${index}`, item.value, { at: index === 0 ? '<' : '<0.1', duration: 1 }),
  )

  step(2, '+=0.4')
  tl.fromTo(q('og'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.3 })
  OPEN_GRAPH.forEach((row, index) =>
    scramble(`og-${index}-value`, row.value, { at: '<0.12', duration: 0.6, chars: 'lowerCase' }),
  )

  step(3, '+=0.4')
  tl.fromTo(q('tw'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.3 })
  TWITTER.forEach((row, index) =>
    scramble(`tw-${index}-value`, row.value, { at: '<0.12', duration: 0.6, chars: 'lowerCase' }),
  )
  move(`${COPIED}-copy`, { at: '+=0.2' })
  click(`${COPIED}-copy`)
  tl.to(q(`${COPIED}-copy`), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q(`${COPIED}-done`),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  tl.to(q(COPIED), { borderColor: 'rgba(56,189,248,0.6)', duration: 0.2 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function Row({
  d,
  label,
  value,
  wide = false,
}: {
  d: string
  label: string
  value: string
  wide?: boolean
}) {
  return (
    <div
      data-d={d}
      className="flex items-start gap-1.5 rounded-md border border-line bg-ink/[0.03] px-2 py-1"
    >
      <div className="min-w-0 flex-1">
        <p className="text-[8.5px] text-muted">{label}</p>
        <p
          data-d={`${d}-value`}
          className={
            wide
              ? 'min-h-[28px] text-[10px] leading-snug text-ink'
              : 'h-[15px] truncate text-[10px] text-ink'
          }
        >
          {value}
        </p>
      </div>
      <span className="relative mt-0.5 size-3 shrink-0 text-muted">
        <span data-d={`${d}-copy`} className="absolute inset-0">
          <CopyIcon className="size-3" />
        </span>
        <span data-d={`${d}-done`} className="absolute inset-0 text-[var(--accent)] opacity-0">
          <CheckIcon className="size-3" />
        </span>
      </span>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Page Info reading a page’s title, canonical, document checks, Open Graph and Twitter tags"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="grid h-full grid-cols-2 gap-2">
          <div className="flex flex-col gap-1.5">
            {BASICS.map((row, index) => (
              <Row
                key={row.label}
                d={`basic-${index}`}
                label={row.label}
                value=""
                wide={index === 2}
              />
            ))}
            <div className="grid grid-cols-3 gap-1.5">
              {CHECKS.map((item) => (
                <div
                  key={item.label}
                  data-d="check"
                  className="rounded-md border border-line bg-ink/[0.03] px-2 py-1 opacity-0"
                >
                  <p className="text-[8.5px] text-muted">{item.label}</p>
                  <p
                    className="text-[10px] text-ink"
                    style={{ color: item.value === '✓' ? '#34d399' : undefined }}
                  >
                    {item.value}
                  </p>
                </div>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-1.5">
              {COUNTS.map((item, index) => (
                <div
                  key={item.label}
                  data-d="count"
                  className="rounded-md border border-line bg-ink/[0.03] py-1.5 text-center opacity-0"
                >
                  <p
                    data-d={`count-${index}`}
                    className="text-[16px] font-semibold tabular-nums text-[var(--accent)]"
                  >
                    0
                  </p>
                  <p className="text-[8.5px] text-muted">{item.label}</p>
                </div>
              ))}
            </div>
          </div>
          <div className="flex flex-col gap-2">
            <div data-d="og" className="space-y-1 rounded-lg border border-line p-1.5 opacity-0">
              <p className="text-[10px] font-medium text-ink">Open Graph</p>
              {OPEN_GRAPH.map((row, index) => (
                <Row key={row.label} d={`og-${index}`} label={row.label} value="" />
              ))}
            </div>
            <div data-d="tw" className="space-y-1 rounded-lg border border-line p-1.5 opacity-0">
              <p className="text-[10px] font-medium text-ink">Twitter / X</p>
              {TWITTER.map((row, index) => (
                <Row key={row.label} d={`tw-${index}`} label={row.label} value="" />
              ))}
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
